/** Bounded JSON payment artifacts and a fixed interpreter; generated bytes are never executed as code. */
import { createHash } from 'node:crypto'
import { isDeepStrictEqual } from 'node:util'
import { z } from 'zod'

/** The only error codes a policy can authorize for retry. Unknown external errors always terminate. */
export type PaymentRetryableError = 'NETWORK_TIMEOUT' | 'PAYMENT_DECLINED' | 'RATE_LIMITED'

/** A flat JSON value: bounded Unicode text, a safe integer, a boolean, or null. */
export type PaymentScalar = string | number | boolean | null

/** Request fields are data only; each attempt preserves all original fields. */
export type PaymentBody = Readonly<Record<string, PaymentScalar>>

/** One scripted external result, or the terminal interpreter result. */
export type PaymentResponse = { readonly kind: 'accepted' } | { readonly kind: 'error'; readonly code: string }

/** A policy artifact controls required fields and bounded retries, without embedded expressions. */
export interface PaymentPolicy {
  readonly version: 1
  readonly requiredFields: readonly string[]
  readonly maxRetries: number
  readonly retryableErrors: readonly PaymentRetryableError[]
}

/** The final scripted response repeats if the bounded interpreter needs further attempts. */
export interface PaymentInput {
  readonly body: PaymentBody | null
  readonly responses: readonly PaymentResponse[]
}

/** Complete requests and terminal result, computed by the interpreter rather than self-reported by an Agent. */
export interface PaymentTrace {
  readonly requests: readonly PaymentBody[]
  readonly outcome: PaymentResponse
}

/** QA supplies complete expected traces for between one and thirty-two distinct cases. */
export interface PaymentCases {
  readonly version: 1
  readonly cases: readonly { readonly id: string; readonly input: PaymentInput; readonly expected: PaymentTrace }[]
}

/** Exact submitted UTF-8 text and its byte identity; sealing does not normalize JSON or truncate invalid artifacts. */
export interface SealedDataArtifact {
  readonly text: string
  readonly bytes: number
  readonly sha256: string
}

/** Artifact rejection codes describe data validity, not business correctness. */
export type DataArtifactErrorCode = 'missing' | 'byte-limit' | 'invalid-utf8' | 'integrity' | 'json' | 'schema'

/** Safe parser error that does not echo model-generated content. */
export class DataArtifactError extends Error {
  constructor(readonly code: DataArtifactErrorCode) {
    super('payment data artifact: ' + code)
    this.name = 'DataArtifactError'
  }
}

const MAX_ARTIFACT_BYTES = 65_536
const identifier = z.string().regex(/^(?!__proto__$)[A-Za-z_][A-Za-z0-9_-]{0,63}$/)
const errorCode = z.string().regex(/^[A-Za-z_][A-Za-z0-9_-]{0,63}$/)
const retryableError = z.enum(['NETWORK_TIMEOUT', 'PAYMENT_DECLINED', 'RATE_LIMITED'])
const scalar = z.union([
  z.string().refine(value => Array.from(value).length <= 256, 'at most 256 Unicode code points').meta({ maxLength: 256 }),
  z.number().int().min(Number.MIN_SAFE_INTEGER).max(Number.MAX_SAFE_INTEGER),
  z.boolean(),
  z.null(),
])
const bodySchema = z.record(identifier, scalar)
  .refine(value => Object.keys(value).length <= 16, 'at most 16 fields').meta({ maxProperties: 16 })
const responseSchema = z.discriminatedUnion('kind', [
  z.strictObject({ kind: z.literal('accepted') }),
  z.strictObject({ kind: z.literal('error'), code: errorCode }),
])
const policySchema = z.strictObject({
  version: z.literal(1),
  requiredFields: z.array(identifier).min(1).max(4)
    .refine(values => new Set(values).size === values.length, 'distinct fields').meta({ uniqueItems: true }),
  maxRetries: z.number().int().min(0).max(10),
  retryableErrors: z.array(retryableError).max(3)
    .refine(values => new Set(values).size === values.length, 'distinct errors').meta({ uniqueItems: true }),
})
const inputSchema = z.strictObject({
  body: bodySchema.nullable(),
  responses: z.array(responseSchema).min(1).max(12),
})
const traceSchema = z.strictObject({
  requests: z.array(bodySchema).max(11),
  outcome: responseSchema,
})
const casesSchema = z.strictObject({
  version: z.literal(1),
  cases: z.array(z.strictObject({ id: identifier, input: inputSchema, expected: traceSchema })).min(1).max(32)
    .refine(cases => new Set(cases.map(item => item.id)).size === cases.length, 'distinct case ids')
    .describe('Case ids must be distinct.'),
})

/** Closed public policy schema. Business-correct retry codes and limits are supplied separately by the task. */
export const paymentPolicyJsonSchema = z.toJSONSchema(policySchema)

/** Closed public QA schema. Unique case ids are additionally checked by parseCases. */
export const paymentCasesJsonSchema = z.toJSONSchema(casesSchema)

/**
 * Seal complete submitted text, including invalid or oversized JSON, without changing its bytes.
 * @param text - Original UTF-8 file content; unpaired UTF-16 surrogates cannot represent original UTF-8 bytes.
 * @returns Frozen content, its complete byte length, and lowercase SHA-256 digest.
 */
export function sealDataArtifact(text: string): SealedDataArtifact {
  const bytes = Buffer.from(text, 'utf8')
  if (bytes.toString('utf8') !== text) throw new DataArtifactError('invalid-utf8')
  return Object.freeze({ text, bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') })
}

function parseArtifact<T>(artifact: SealedDataArtifact, schema: z.ZodType<T>): T {
  if (Buffer.byteLength(artifact.text, 'utf8') > MAX_ARTIFACT_BYTES) throw new DataArtifactError('byte-limit')
  const actual = sealDataArtifact(artifact.text)
  if (actual.bytes !== artifact.bytes || actual.sha256 !== artifact.sha256) throw new DataArtifactError('integrity')
  let decoded: unknown
  try { decoded = JSON.parse(artifact.text) } catch { throw new DataArtifactError('json') }
  const parsed = schema.safeParse(decoded)
  // Closed validation must not discard reserved object keys or other submitted data.
  if (!parsed.success || !isDeepStrictEqual(parsed.data, decoded)) throw new DataArtifactError('schema')
  return parsed.data
}

/**
 * Parse one complete sealed policy with closed fields and protocol byte, scalar, and retry bounds.
 * @param artifact - Exact sealed file content.
 * @returns Detached validated policy; throws DataArtifactError for invalid submitted data.
 */
export function parsePolicy(artifact: SealedDataArtifact): PaymentPolicy {
  return parseArtifact(artifact, policySchema)
}

/**
 * Parse QA inputs and full expected traces; there is no score or pass field.
 * @param artifact - Exact sealed file content.
 * @returns Detached bounded cases with distinct ids; throws DataArtifactError for invalid submitted data.
 */
export function parseCases(artifact: SealedDataArtifact): PaymentCases {
  return parseArtifact(artifact, casesSchema)
}

/**
 * Interpret a validated policy and input without evaluating code, expressions, files, or network requests.
 * Required fields must be own properties whose values are neither null nor empty strings; zero and false are valid.
 * @param policy - Parsed policy or a trusted fixture with the same finite limits.
 * @param input - Parsed input or a trusted fixture. Unknown external errors terminate even when later responses succeed.
 * @returns Detached full trace, with at most eleven requests. Invalid bodies produce CONTRACT_INVALID_PAYLOAD and no requests.
 */
export function executePayment(policy: PaymentPolicy, input: PaymentInput): PaymentTrace {
  const body = input.body
  if (body === null || policy.requiredFields.some(field => !Object.hasOwn(body, field) || body[field] === null || body[field] === '')) {
    return { requests: [], outcome: { kind: 'error', code: 'CONTRACT_INVALID_PAYLOAD' } }
  }
  const requests: PaymentBody[] = []
  for (let attempt = 0; attempt <= policy.maxRetries; attempt++) {
    requests.push({ ...body })
    const outcome = input.responses[Math.min(attempt, input.responses.length - 1)]
    if (!outcome) throw new Error('payment fixture requires at least one response')
    if (outcome.kind === 'accepted') return { requests, outcome: { ...outcome } }
    const known = retryableError.safeParse(outcome.code)
    if (attempt === policy.maxRetries || !known.success || !policy.retryableErrors.includes(known.data)) {
      return { requests, outcome: { ...outcome } }
    }
  }
  throw new Error('payment fixture requires a nonnegative retry limit')
}

/** Per-artifact validity and behavior outcome; failed means valid JSON that did not satisfy the independent checks. */
export type DataGradeStatus = 'invalid' | 'failed' | 'passed'

/** The parent grader retains identities even for malformed artifacts. Missing files have no identity. */
export interface DataArtifactGrade {
  readonly status: DataGradeStatus
  readonly artifact: { readonly bytes: number; readonly sha256: string } | null
  readonly error: DataArtifactErrorCode | null
}

/** Candidate policy behavior against the reference on each hidden input. */
export interface PaymentPolicyGrade extends DataArtifactGrade {
  readonly checks: readonly {
    readonly index: number
    readonly passed: boolean
    readonly expected: PaymentTrace
    readonly actual: PaymentTrace
  }[]
}

/** QA must pass the independent reference and distinguish every registered mutant. */
export interface PaymentCasesGrade extends DataArtifactGrade {
  readonly referenceChecks: readonly { readonly id: string; readonly passed: boolean; readonly actual: PaymentTrace }[]
  readonly mutants: readonly { readonly id: string; readonly killed: boolean; readonly detectedBy: readonly string[] }[]
}

/** Parent-only grading inputs; never expose the reference, hidden inputs, or mutants through model tools. */
export interface DataArtifactGradeRequest {
  readonly policy: SealedDataArtifact | null
  readonly cases: SealedDataArtifact | null
  readonly reference: PaymentPolicy
  readonly hiddenInputs: readonly PaymentInput[]
  readonly mutants: readonly { readonly id: string; readonly policy: PaymentPolicy }[]
}

/** Separate policy and QA results prevent a broken client from being counted as useful QA detection. */
export interface DataArtifactGrades {
  readonly policy: PaymentPolicyGrade
  readonly tests: PaymentCasesGrade
  readonly pairStatus: DataGradeStatus
}

function identity(artifact: SealedDataArtifact | null): DataArtifactGrade['artifact'] {
  return artifact === null ? null : { bytes: artifact.bytes, sha256: artifact.sha256 }
}

function parsed<T>(artifact: SealedDataArtifact | null, parse: (value: SealedDataArtifact) => T):
  { readonly value: T; readonly error: null } | { readonly value: null; readonly error: DataArtifactErrorCode } {
  if (artifact === null) return { value: null, error: 'missing' }
  try { return { value: parse(artifact), error: null } } catch (error) {
    if (!(error instanceof DataArtifactError)) throw error
    return { value: null, error: error.code }
  }
}

/**
 * Grade sealed artifacts independently with the fixed interpreter. Hidden evidence remains in the parent result.
 * Empty hidden input or mutant sets are fixture errors, not successful trials.
 * @param request - Submitted artifacts and the separate trusted reference, hidden inputs, and distinct mutants.
 * @returns Policy checks, reference-valid QA mutation detection, and the combined result; no model-reported score is used.
 */
export function gradeDataArtifacts(request: DataArtifactGradeRequest): DataArtifactGrades {
  if (!request.hiddenInputs.length || !request.mutants.length
    || new Set(request.mutants.map(mutant => mutant.id)).size !== request.mutants.length) {
    throw new Error('data artifact grading requires hidden inputs and distinct named mutants')
  }
  const policy = parsed(request.policy, parsePolicy)
  const cases = parsed(request.cases, parseCases)
  const checks = policy.value === null ? [] : request.hiddenInputs.map((input, index) => {
    const expected = executePayment(request.reference, input)
    const actual = executePayment(policy.value, input)
    return { index, passed: isDeepStrictEqual(actual, expected), expected, actual }
  })
  const referenceChecks = cases.value === null ? [] : cases.value.cases.map((item) => {
    const actual = executePayment(request.reference, item.input)
    return { id: item.id, passed: isDeepStrictEqual(actual, item.expected), actual }
  })
  const referencePassed = cases.value !== null && referenceChecks.every(check => check.passed)
  const mutants = cases.value === null ? [] : request.mutants.map(mutant => ({
    id: mutant.id,
    detectedBy: cases.value.cases.filter(item =>
      !isDeepStrictEqual(executePayment(mutant.policy, item.input), item.expected)).map(item => item.id),
  })).map(mutant => ({ ...mutant, killed: referencePassed && mutant.detectedBy.length > 0 }))
  const policyStatus = policy.error !== null ? 'invalid' : checks.every(check => check.passed) ? 'passed' : 'failed'
  const testsStatus = cases.error !== null ? 'invalid'
    : referencePassed && mutants.every(mutant => mutant.killed) ? 'passed' : 'failed'
  return {
    policy: { status: policyStatus, artifact: identity(request.policy), error: policy.error, checks },
    tests: { status: testsStatus, artifact: identity(request.cases), error: cases.error, referenceChecks, mutants },
    pairStatus: policyStatus === 'invalid' || testsStatus === 'invalid' ? 'invalid'
      : policyStatus === 'passed' && testsStatus === 'passed' ? 'passed' : 'failed',
  }
}
